import{_ as l,o as i,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-08-01 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-08-01 :: Ceph Performance Meeting","date":"2019-08-01T00:00:00.000Z","updated":"2019-08-03T00:00:00.000Z","tags":["Ceph","BlueStore","RocksDB","Performance","PR Review"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-08-01_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-08-01_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),t={name:"posts/2019/2019-08-01_-_-_Ceph_Performance_Meeting.md"};function a(s,e,n,p,_,c){return i(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Neha, Josh, Adam, Eric, Igor, Aaron, Mark, Sam 等</p><p><strong>会议主题</strong>：</p><ol><li><p><strong>本周 PR 回顾</strong>：</p><ul><li>合并了支持 RocksDB 新版本的 master，增加了 proxy cache 和 range 功能。</li><li>Moshing 和 Peng 提交的 PR 减少了 BlueStore 的唤醒次数，可能带来性能提升。</li><li>May 提交的 PR 通过测试，为 BlueStore 带来了 25-30% 的随机小写性能提升。</li><li>Trim cache on ad PR 已合并到 P 上。</li><li>Eric 提交的 RGW 效率提升 PR 已进入测试阶段。</li><li>Adams 提交的 PR 正在测试中，希望尽快合并。</li></ul></li><li><p><strong>RFC：将 BlueFS Alexeyes 默认值设置为与 BlueStore 相同，并设置为 16K</strong>：</p><ul><li>背景和目的：为了解决 BlueFS 和 BlueStore 在碎片化方面的差异，提出将两者分配大小设置为相同的 RFC。</li><li>讨论：Neha 介绍了 RFC 的背景和目的，Josh 解释了 PR 的具体实现方式，Mark 提出性能影响的担忧，并希望进行更多测试，Adam 认为将分配大小设置为 16K 是一个合理的折衷方案，决定将 PR 作为高优先级任务进行测试和评估。</li></ul></li><li><p><strong>其他议题</strong>：</p><ul><li>Igor 的 RocksDB 提示文件 PR 仍在进行中。</li><li>6.1.2 版本已合并到 master，并计划将其回滚到 Nautilus。</li><li>MDS 和 Demon 内存限制调整 PR 正在开发中。</li><li>OpTracker 事件优化 PR 已与 Patrick 达成共识。</li><li>Igor 的自动调整 PR 需要重构和重置。</li></ul></li><li><p><strong>行动计划</strong>：</p><ul><li>对 BlueFS Alexeyes 默认值设置为 16K 的 PR 进行测试和评估。</li><li>继续开发其他 PR。</li><li>讨论将 RocksDB 6.1.2 版本回滚到 Nautilus 的可行性。</li><li>关注 Igor 的 RocksDB 提示文件 PR 的进展。</li></ul></li></ol><p><strong>后续会议</strong>：</p><ul><li>下周会议可能讨论 Sam 关于 LoRan 内部延迟的分享。</li></ul><p><strong>改进点</strong>：</p><ul><li>更详细地描述了 RFC 的背景和目的，以及相关的讨论内容。</li><li>补充了 Igor 的 RocksDB 提示文件 PR 和自动调整 PR 的进展情况。</li><li>确保了所有 Ceph 相关的关键字得到保留。</li></ul>',9)])])}const P=l(t,[["render",a]]);export{u as __pageData,P as default};
